mapper.select:
/* PayMapper.selectEasypayResult : 이지페이 결제결과조회 */ SELECT MAX(inv.INVOICE_JOB_NO) AS INVOICE_JOB_NO ,ISNULL(MAX(inv.INVOICE_NO_GROUP), MAX(inv.INVOICE_NO)) AS INVOICE_NO ,MAX(inv.ACCOUNT_CODE) AS ACCOUNT_CODE ,SUM(inv.AMOUNT_TOTAL_LOC) AS AMOUNT ,( SELECT CASE WHEN bl.BL_TYPE_MH = 'H' THEN CONCAT(bl.HBL_NO, '/', ISNULL(bl.CONSIGNEE_NAME, '')) ELSE CASE WHEN bl.SOLUTION = 'FMS' AND bl.BOUND IN('AIR', 'SEA') THEN CONCAT(bl.MBL_NO, '/', ISNULL(bl.CONSIGNEE_NAME, '')) ELSE bl.MBL_NO END END FROM TB_COM_OD od INNER JOIN TB_COM_OBL bl ON bl.OBL_JOB_NO = od.OBL_JOB_NO WHERE od.OD_JOB_NO = MAX(inv.OD_JOB_NO) ) AS GOODS_NAME
,MAX(res.PAYMENT_STATUS) AS PAYMENT_STATUS ,MAX(res.APPROVAL_REQ_DATE) AS APPROVAL_REQ_DATE ,MAX(res.SHOP_TRANSACTION_ID) AS SHOP_TRANSACTION_ID ,MAX(res.RES_CD) AS RES_CD ,MAX(res.RES_MSG) AS RES_MSG ,MAX(res.PG_CNO) AS PG_CNO ,MAX(res.BANK_NAME) AS BANK_NAME ,MAX(res.ACCOUNT_NO) AS ACCOUNT_NO ,MAX(res.DEPOSIT_NAME) AS DEPOSIT_NAME
,MAX(od.SHIPPER_NAME) AS SHIPPER_NAME ,MAX(od.SHIPPER_ADDRESS) AS SHIPPER_ADDRESS ,MAX(od.CONSIGNEE_NAME) AS CONSIGNEE_NAME ,MAX(od.CONSIGNEE_ADDRESS) AS CONSIGNEE_ADDRESS ,MAX(od.PIECES) AS PIECES ,MAX(od.GWT) AS GWT ,MAX(od.ITEM_NAME) AS ITEM_NAME
FROM TB_SAS_INVOICE inv
LEFT JOIN TB_SAS_PAY_RESULT res ON res.INVOICE_NO = inv.${invoiceNoField} AND res.SHOP_TRANSACTION_ID = #{shopTransactionId}
INNER JOIN ( SELECT bl.HBL_NO ,bl.MBL_NO ,bl.BL_TYPE_MH ,bl.SOLUTION ,bl.BOUND ,bl.SHIPPER_NAME ,CONCAT(ISNULL(bl.SHIPPER_ADDRESS, ''),ISNULL(bl.SHIPPER_ADDRESS_A, ''),ISNULL(bl.SHIPPER_ADDRESS_B, ''),ISNULL(bl.SHIPPER_ADDRESS_C, ''),ISNULL(bl.SHIPPER_ADDRESS_D, '')) AS SHIPPER_ADDRESS ,bl.CONSIGNEE_NAME ,CONCAT(ISNULL(bl.CONSIGNEE_ADDRESS, ''),ISNULL(bl.CONSIGNEE_ADDRESS_A, ''),ISNULL(bl.CONSIGNEE_ADDRESS_B, ''),ISNULL(bl.CONSIGNEE_ADDRESS_C, ''),ISNULL(bl.CONSIGNEE_ADDRESS_D, '')) AS CONSIGNEE_ADDRESS ,bl.PIECES ,bl.GWT ,bl.ITEM_NAME ,#{invoiceNo} AS ${invoiceNoField} FROM TB_COM_OD od INNER JOIN TB_COM_OBL bl ON bl.OBL_JOB_NO = od.OBL_JOB_NO WHERE od.OD_JOB_NO = (SELECT MAX(OD_JOB_NO) FROM TB_SAS_INVOICE WHERE ${invoiceNoField} = #{invoiceNo}) ) od ON od.${invoiceNoField} = inv.${invoiceNoField}
WHERE inv.ENT_CODE = #{entCode} AND inv.${invoiceNoField} = #{invoiceNo} GROUP BY inv.${invoiceNoField}

/* PayMapper.selectEasypayInvoice : 결제 정산서 조회 */ SELECT A.* FROM(
SELECT #{item.SHIPPER_NAME} AS SHIPPER_NAME ,#{item.SHIPPER_ADDRESS} AS SHIPPER_ADDRESS ,#{item.CONSIGNEE_NAME} AS CONSIGNEE_NAME ,#{item.CONSIGNEE_ADDRESS} AS CONSIGNEE_ADDRESS ,#{item.ITEM_NAME} AS ITEM_NAME ,#{item.SHOP_ORDER_NO} AS SHOP_ORDER_NO ,#{item.INVOICE_NO} AS INVOICE_NO ,ISNULL((SELECT MAX(CASE WHEN PAYMENT_STATUS IN ('R','S') THEN 1 ELSE 0 END) FROM TB_SAS_PAY_RESULT WHERE INVOICE_NO = #{item.SHOP_ORDER_NO}), 0) AS PAYMENT ,SUM(bl.PIECES) AS PIECES ,SUM(bl.GWT) AS GWT ,MAX(inv.INVOICE_DATE) AS INVOICE_DATE ,MAX(inv.ACCOUNT_CODE) AS ACCOUNT_CODE ,MAX(inv.AMOUNT_TOTAL_LOC) AS AMOUNT FROM TB_SAS_INVOICE inv INNER JOIN TB_COM_OD od ON od.OD_JOB_NO = inv.OD_JOB_NO INNER JOIN TB_COM_OBL bl ON bl.OBL_JOB_NO = od.OBL_JOB_NO WHERE inv.${item.INVOICE_NO_FIELD} = #{item.SHOP_ORDER_NO} GROUP BY inv.${item.INVOICE_NO_FIELD}
) A WHERE A.PAYMENT = 0

/* PayMapper.selectEntCode : 도입사코드조회 */
	SELECT TOP 1 ENT_CODE
	FROM TB_SMS_ENTERPRISE
	WHERE EASYPAY_MALL_ID = #{easypayMallId}

mapper.insert:
/* PayMapper.insertPayResult : 정산서 결제 승인정보 저장 */
	INSERT INTO TB_SAS_PAY_RESULT(
		   PAY_JOB_NO
		  ,ENT_CODE
		  ,INVOICE_NO
		  ,INV_GROUP_YN
		  ,PAY_TYPE
		  ,AMOUNT
		  ,SHOP_TRANSACTION_ID
		  ,PAY_METHOD_TYPE_CODE
		  ,PAYMENT_STATUS
		  ,APPROVAL_REQ_DATE
		  ,INPUT_METHOD
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME

		  ,RES_CD
		  ,RES_MSG
		  ,PG_CNO
		  ,NOTI_TYPE
		  ,TRANSACTION_DATE_TIME
		  ,STATUS_CODE
		  ,STATUS_MESSAGE
		  ,APPROVAL_NO
		  ,APPROVAL_DATE_TIME
		  ,CP_CODE
		  ,MULTI_CARD_AMOUNT
		  ,MULTI_PNT_AMOUNT
		  ,BANK_NAME
		  ,ACCOUNT_NO
		  ,DEPOSIT_NAME
		  ,EXPIRY_DATE
		  ,REMARKS

	)VALUES(
		   #{payJobNo}
		  ,#{entCode}
		  ,#{invoiceNo}
		  ,#{invGroupYn}
		  ,#{payType}
		  ,#{amount}
		  ,#{shopTransactionId}
		  ,#{payMethodTypeCode}
		  ,#{paymentStatus}
		  ,#{approvalReqDate}
		  ,#{inputMethod}
		  ,#{userId}
		  ,GETDATE()

		  ,#{resCd}
		  ,#{resMsg}
		  ,#{pgCno}
		  ,#{notiType}
		  ,#{transactionDateTime}
		  ,#{statusCode}
		  ,#{statusMessage}
		  ,#{approvalNo}
		  ,#{approvalDateTime}
		  ,#{cpCode}
		  ,#{multiCardAmount}
		  ,#{multiPntAmount}
		  ,#{bankName}
		  ,#{accountNo}
		  ,#{depositName}
		  ,#{expiryDate}
		  ,#{remarks}

	)

mapper.update:
/* PayMapper.updatePayResult : 정산서 결제 승인정보 저장 */
	UPDATE TB_SAS_PAY_RESULT SET
		   RES_CD = #{resCd}
		  ,RES_MSG = #{resMsg}
		  ,PG_CNO = #{pgCno}
		  ,AMOUNT = #{amount}
		  ,TRANSACTION_DATE_TIME = #{transactionDateTime}
		  ,STATUS_CODE = #{statusCode}
		  ,STATUS_MESSAGE = #{statusMessage}
		  ,APPROVAL_NO = #{approvalNo}
		  ,APPROVAL_DATE_TIME = #{approvalDateTime}
		  ,CP_CODE = #{cpCode}
		  ,MULTI_CARD_AMOUNT = #{multiCardAmount}
		  ,MULTI_PNT_AMOUNT = #{multiPntAmount}
		  ,BANK_NAME = #{bankName}
		  ,ACCOUNT_NO = #{accountNo}
		  ,DEPOSIT_NAME = #{depositName}
		  ,EXPIRY_DATE = #{expiryDate}
		  ,PAYMENT_STATUS = #{paymentStatus}
		  ,REMARKS = #{remarks}
	WHERE PAY_JOB_NO = #{payJobNo}
